const http = require("http");
const fs = require("fs");
const path = require("path");

function loadEnv(file) {
  const env = {};
  const text = fs.readFileSync(file, "utf8");
  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const idx = trimmed.indexOf("=");
    if (idx === -1) continue;
    env[trimmed.slice(0, idx).trim()] = trimmed.slice(idx + 1).trim();
  }
  return env;
}

const env = loadEnv(path.join(__dirname, ".env"));
const AI_API_BASE = env.AI_API_BASE;
const AI_API_KEY = env.AI_API_KEY;
const AI_MODEL = env.AI_MODEL || "gpt-4o-mini";
const PORT = Number(env.PORT) || 7787;
const HOST = env.HOST || "127.0.0.1";

const tasks = JSON.parse(fs.readFileSync(path.join(__dirname, "tasks.json"), "utf8"));
const taskById = Object.fromEntries(tasks.map((t) => [t.id, t]));
const CONTENT_MD_PATH = path.join(__dirname, "Tasks Content.md");
const LONGREADS_JSON_PATH = path.join(__dirname, "longreads.json");
const LONGREADS_MD_PATH = path.join(__dirname, "Longreads Content.md");
const CHAPTER_TITLES = {
  1: "Промптинг: основы",
  2: "Контрастивный пример",
  3: "Символическая запись",
  4: "Сонет",
  5: "Сравнение режимов",
  6: "CLI и агенты",
};

const longreadsIndex = JSON.parse(fs.readFileSync(LONGREADS_JSON_PATH, "utf8"));
const longreadById = Object.fromEntries(longreadsIndex.map((l) => [l.id, l]));

const PERSONAS_JSON_PATH = path.join(__dirname, "personas.json");
const CLI_FILES_DIR = path.join(__dirname, "cli-lab-files");

const personas = JSON.parse(fs.readFileSync(PERSONAS_JSON_PATH, "utf8"));
const personaById = Object.fromEntries(personas.map((p) => [p.id, p]));

function walkCliDir(dir, relBase) {
  const entries = fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => {
    if (a.isDirectory() !== b.isDirectory()) return a.isDirectory() ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
  return entries.map((entry) => {
    const rel = relBase ? `${relBase}/${entry.name}` : entry.name;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      return { type: "dir", name: entry.name, path: rel, children: walkCliDir(full, rel) };
    }
    return { type: "file", name: entry.name, path: rel, content: fs.readFileSync(full, "utf8") };
  });
}

function loadCliTree() {
  return walkCliDir(CLI_FILES_DIR, "");
}

function flattenCliFiles(nodes, out) {
  out = out || [];
  for (const node of nodes) {
    if (node.type === "file") out.push(node);
    else flattenCliFiles(node.children, out);
  }
  return out;
}

function parseTaskContentMd(text) {
  const blocks = text.split(/\n(?=## )/).filter((b) => b.trim().startsWith("## "));
  const content = {};
  for (const block of blocks) {
    const header = block.match(/^## (\S+) — (.+)$/m);
    if (!header) continue;
    const id = header[1].trim();
    const title = header[2].trim();

    const field = (label) => block.match(new RegExp(`\\*\\*${label}:\\*\\*\\s*([\\s\\S]*?)(?=\\n\\*\\*|\\n##|$)`));
    const situ = field("Ситуация");
    const instr = field("Инструкция");
    const visibleBlock = field("Как мы будем оценивать");
    const rubricBlock = field("Скрытая рубрика");
    // Необязательные поля для панели сравнения (глава 5) и CLI-заданий (глава 6).
    const modeField = field("Режим");
    const leftField = field("Левая панель");
    const rightField = field("Правая панель");
    const agentField = field("Агент");
    const fileField = field("Файл");

    const parseBullets = (text) =>
      text
        .split("\n")
        .map((l) => l.trim())
        .filter((l) => l.startsWith("-"))
        .map((l) => l.replace(/^-\s*/, "").trim());

    content[id] = {
      title,
      role: situ ? situ[1].trim() : "",
      instruction: instr ? instr[1].trim() : "",
      visibleRubric: visibleBlock ? parseBullets(visibleBlock[1]) : [],
      rubric: rubricBlock ? parseBullets(rubricBlock[1]) : [],
      mode: modeField ? modeField[1].trim() : "",
      leftPanel: leftField ? leftField[1].trim() : "",
      rightPanel: rightField ? rightField[1].trim() : "",
      personaId: agentField ? agentField[1].trim() : "",
      fileId: fileField ? fileField[1].trim() : "",
    };
  }
  return content;
}

function getAllContent() {
  return parseTaskContentMd(fs.readFileSync(CONTENT_MD_PATH, "utf8"));
}

function fullTask(id, allContent) {
  const structural = taskById[id];
  if (!structural) return null;
  const content = (allContent || getAllContent())[id];
  if (!content) throw new Error(`No content block for task "${id}" in Tasks Content.md`);
  return { ...structural, ...content };
}

function parseLongreadsMd(text) {
  const blocks = text.split(/\n(?=## )/).filter((b) => b.trim().startsWith("## "));
  const content = {};
  for (const block of blocks) {
    const header = block.match(/^## (\S+) — (.+)$/m);
    if (!header) continue;
    const id = header[1].trim();
    const title = header[2].trim();
    const lead = block.match(/\*\*Лид:\*\*\s*([\s\S]*?)(?=\n\*\*|\n##|$)/);
    const body = block.match(/\*\*Текст:\*\*\s*([\s\S]*?)(?=\n##|$)/);
    content[id] = {
      title,
      lead: lead ? lead[1].trim() : "",
      body: body ? body[1].trim() : "",
    };
  }
  return content;
}

function getLongreadContent() {
  return parseLongreadsMd(fs.readFileSync(LONGREADS_MD_PATH, "utf8"));
}

function chapterProgress(n) {
  const rows = tasks.filter((t) => t.chapter === n);
  const done = rows.filter((t) => state.progress[t.id] && state.progress[t.id].passed).length;
  return {
    chapter: n,
    title: CHAPTER_TITLES[n] || "Глава " + n,
    done,
    total: rows.length,
    complete: rows.length > 0 && done === rows.length,
  };
}

function isLongreadUnlocked(item) {
  const need = item.unlockChapters || [];
  return need.every((ch) => chapterProgress(ch).complete);
}

function unlockHint(item) {
  const need = item.unlockChapters || [];
  if (!need.length) return "";
  const bits = need.map((ch) => {
    const p = chapterProgress(ch);
    return `${p.chapter} «${p.title}» (зачтено ${p.done} из ${p.total})`;
  });
  if (need.length === 1) {
    return `Откроется после главы ${bits[0]}.`;

