const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
};

async function callChat(messages, { json = false, temperature = 0.8 } = {}) {
  const body = { model: AI_MODEL, messages, temperature };
  if (json) body.response_format = { type: "json_object" };

  const res = await fetch(`${AI_API_BASE}/v1/chat/completions`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${AI_API_KEY}` },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`AI backend ${res.status}: ${await res.text()}`);
  const data = await res.json();
  return { content: data.choices[0].message.content, tokens: data.usage ? data.usage.total_tokens : 0 };
}

async function runStudentPrompt(studentPrompt) {
  return callChat([{ role: "user", content: studentPrompt }]);
}

async function judge(task, transcriptText) {
  const rubricList = task.rubric.map((r, i) => `${i + 1}. ${r}`).join("\n");
  const isReflection = task.type === "reflection";
  const secrecyNote = `Рубрика — служебный документ для проверки, студент её не видит. В поле feedback НИКОГДА не цитируй и не пересказывай формулировки критериев дословно или близко к тексту — студент не должен по обратной связи реверс-инжинирить точный текст рубрики. Пиши feedback как обычный человеческий совет по существу (что улучшить или за что похвала), не в форме "критерий N не выполнен".`;
  const systemPrompt = isReflection
    ? `Ты — экзаменатор в тренажёре по промптингу, проверяешь письменный рефлексивный ответ студента (не промпт). Оцени каждый критерий рубрики отдельно (true/false) для внутреннего решения. Вердикт "passed" — true только если выполнены ВСЕ критерии. ${secrecyNote} Ответь строго JSON: {"passed": boolean, "feedback": string}. feedback — 1-2 предложения на русском.`
    : `Ты — строгий, но справедливый экзаменатор в тренажёре по промптингу. Тебе дана задача и полная стенограмма попытки студента — одного или нескольких промптов подряд и ответов модели на каждый из них, в хронологическом порядке. Оцени каждый критерий рубрики отдельно (true/false) для внутреннего решения, учитывая всю последовательность целиком (например, если рубрика требует, чтобы первый промпт делал одно, а второй — другое, проверяй это по реальному порядку промптов в стенограмме). Вердикт "passed" — true только если выполнены ВСЕ критерии. ${secrecyNote} Ответь строго JSON: {"passed": boolean, "feedback": string}. feedback — 1-2 предложения на русском.`;

  const userPrompt = isReflection
    ? `ЗАДАНИЕ: ${task.instruction}\n\nРУБРИКА:\n${rubricList}\n\nОТВЕТ СТУДЕНТА:\n"""${transcriptText}"""`
    : `ЗАДАЧА: ${task.instruction}\n\nРУБРИКА:\n${rubricList}\n\nСТЕНОГРАММА ПОПЫТКИ СТУДЕНТА:\n"""${transcriptText}"""`;

  const { content, tokens } = await callChat(
    [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt },
    ],
    { json: true, temperature: 0 }
  );
  return { verdict: JSON.parse(content), tokens };
}

function buildTranscript(task, messages) {
  if (task.type === "reflection") {
    return messages
      .filter((m) => m.role === "user")
      .map((m) => m.text)
      .join("\n\n");
  }
  const parts = [];
  let n = 0;
  for (const m of messages) {
    if (m.role === "user") {
      n += 1;
      parts.push(`Промпт ${n}:\n${m.text}`);
    } else if (m.role === "model") {
      parts.push(`Ответ модели на промпт ${n}:\n${m.text}`);
    }
  }
  return parts.join("\n\n");
}

function send(res, status, contentType, body) {
  res.writeHead(status, { "Content-Type": contentType });
  res.end(body);
}

function serveStatic(req, res) {
  let filePath = req.url === "/" ? "/index.html" : req.url;
  filePath = path.join(__dirname, "public", filePath.split("?")[0]);
  if (!filePath.startsWith(path.join(__dirname, "public"))) return send(res, 403, "text/plain", "Forbidden");
  fs.readFile(filePath, (err, data) => {
    if (err) return send(res, 404, "text/plain", "Not found");
    send(res, 200, MIME[path.extname(filePath)] || "application/octet-stream", data);
  });
}

async function readJsonBody(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });
}

function publicState() {
  const allContent = getAllContent();
  const chapters = {};
  for (const t of tasks) {
    if (!chapters[t.chapter]) chapters[t.chapter] = [];
    const p = state.progress[t.id];
    chapters[t.chapter].push({
      id: t.id,
      title: (allContent[t.id] || {}).title || t.id,
      type: t.type,
      xp: t.xp,
      passed: p.passed,
    });
  }
  const lr = publicLongreads();
  return {
    totalXp: state.totalXp,
    computeBudget: state.computeBudget,
    computeUsed: state.computeUsed,
    chapters,
    longreadsUnlocked: lr.filter((x) => x.unlocked).length,
    longreadsTotal: lr.length,
  };
}

function spendCompute(tokens) {
  state.computeUsed += tokens;
  state.computeBudget = Math.max(0, state.computeBudget - tokens);
}

