  if (url.pathname === "/api/reset" && req.method === "POST") {
    try {
      const { taskId } = await readJsonBody(req);
      const task = fullTask(taskId);
      if (!task) return send(res, 400, MIME[".json"], JSON.stringify({ error: "unknown task" }));
      const p = state.progress[taskId];
      if (p.xpAwarded) state.totalXp = Math.max(0, state.totalXp - task.xp);
      state.progress[taskId] = {
        passed: false,
        xpAwarded: false,
        hintUsed: false,
        solutionUsed: false,
        messages: [],
      };
      return send(res, 200, MIME[".json"], JSON.stringify({ messages: [], state: publicState() }));
    } catch (e) {
      console.error(e);
      return send(res, 500, MIME[".json"], JSON.stringify({ error: String(e.message || e) }));
    }
  }

  if (url.pathname === "/api/hint" && req.method === "POST") {
    try {
      const { taskId } = await readJsonBody(req);
      const task = fullTask(taskId);
      if (!task) return send(res, 400, MIME[".json"], JSON.stringify({ error: "unknown task" }));
      const p = state.progress[taskId];
      const hintSystem =
        task.type === "reflection"
          ? "Ты — ассистент тренажёра по промптингу. Дай студенту одну наводящую подсказку к письменному рефлексивному ответу: куда смотреть и что сравнить. Не пиши готовый ответ и не пересказывай скрытую рубрику дословно. 2-3 предложения на русском."
          : "Ты — ассистент тренажёра по промптингу. Дай студенту одну наводящую подсказку по заданию ниже, не решая задачу за него и не приводя готовый промпт целиком. 2-3 предложения на русском.";

      const { content, tokens } = await callChat([
        {
          role: "system",
          content: hintSystem,
        },
        { role: "user", content: `ЗАДАНИЕ: ${task.instruction}\n\nРУБРИКА:\n${task.rubric.map((r, i) => `${i + 1}. ${r}`).join("\n")}` },
      ]);
      spendCompute(tokens);
      state.totalXp = Math.max(0, state.totalXp - HINT_COST);
      p.hintUsed = true;
      p.messages.push({ role: "hint", label: "Подсказка", text: content });

      return send(res, 200, MIME[".json"], JSON.stringify({ messages: p.messages, state: publicState() }));
    } catch (e) {
      console.error(e);
      return send(res, 500, MIME[".json"], JSON.stringify({ error: String(e.message || e) }));
    }
  }

  if (url.pathname === "/api/solution" && req.method === "POST") {
    try {
      const { taskId } = await readJsonBody(req);
      const task = fullTask(taskId);
      if (!task) return send(res, 400, MIME[".json"], JSON.stringify({ error: "unknown task" }));
      if (task.type === "reflection" || task.type === "cli")
        return send(res, 400, MIME[".json"], JSON.stringify({ error: "Полное решение недоступно для этого типа задания" }));
      const p = state.progress[taskId];
      if (!p.hintUsed) return send(res, 403, MIME[".json"], JSON.stringify({ error: "Полное решение открывается только после подсказки" }));

      const { content, tokens } = await callChat([
        {
          role: "system",
          content: "Ты — ассистент тренажёра по промптингу. Напиши образцовый промпт, полностью удовлетворяющий рубрике задания ниже. Дай только сам промпт, без пояснений.",
        },
        { role: "user", content: `ЗАДАНИЕ: ${task.instruction}\n\nРУБРИКА:\n${task.rubric.map((r, i) => `${i + 1}. ${r}`).join("\n")}` },
      ]);
      spendCompute(tokens);
      state.totalXp = Math.max(0, state.totalXp - SOLUTION_COST);
      p.solutionUsed = true;
      p.messages.push({ role: "solution", label: "Полное решение", text: content });

      return send(res, 200, MIME[".json"], JSON.stringify({ messages: p.messages, state: publicState() }));
    } catch (e) {
      console.error(e);
      return send(res, 500, MIME[".json"], JSON.stringify({ error: String(e.message || e) }));
    }
  }

  return serveStatic(req, res);
});

server.listen(PORT, HOST, () => {
  console.log(`Prompt trainer running on http://${HOST}:${PORT}`);
});

