// --- 7. корректное завершение --------------------------------------------
replace(
  `server.listen(PORT, HOST, () => {
  console.log(\`Prompt trainer running on http://\${HOST}:\${PORT}\`);
});`,
  `server.listen(PORT, HOST, () => {
  console.log(\`Prompt trainer running on http://\${HOST}:\${PORT}\`);
});

// Docker останавливает контейнер через SIGTERM — дописываем прогресс перед выходом.
for (const signal of ["SIGTERM", "SIGINT"]) {
  process.on(signal, () => {
