    `$p = Get-Process -Id ${pid}; '{0} {1}' -f [math]::Round($p.WorkingSet64/1MB), [math]::Round($p.PrivateMemorySize64/1MB)`]).toString().trim();
  const [ws, priv] = out.split(' ');
  return `рабочий набор ${ws} МБ, приватная ${priv} МБ`;
}

function startEngine(hash) {
  return new Promise((resolve) => {
    const c = spawn(info.path, [], { stdio: ['pipe', 'pipe', 'ignore'], windowsHide: true });
    let buf = '';
    c.stdout.on('data', (d) => {
      buf += d;
      if (buf.includes('readyok')) { buf = ''; c.stdout.removeAllListeners('data'); resolve(c); }
    });
    c.stdin.write(`uci\nsetoption name Threads value 1\nsetoption name Hash value ${hash}\nisready\n`);
  });
}

(async () => {
  const a = await startEngine(16);
  const b = await startEngine(32);
  await new Promise((r) => setTimeout(r, 800));
  console.log('воркер пула (Hash 16):   ', mem(a.pid));
  console.log('аналитический (Hash 32): ', mem(b.pid));
  a.stdin.write('quit\n'); b.stdin.write('quit\n');
})();
EOF
