`const LOGIN_MAX_ATTEMPTS = 10;
const LOGIN_WINDOW_MS = 15 * 60 * 1000;
const loginAttempts = new Map();

// Лимит на адрес ловит случайный перебор, но X-Forwarded-For пишет сам клиент:
// подменяя его на каждой попытке, лимит по адресу можно обойти. Общий лимит на все
// адреса сразу закрывает эту дыру ценой того, что при атаке вход ненадолго
// блокируется и для своих.
const LOGIN_MAX_FAILS_TOTAL = 100;
const loginFailsTotal = { count: 0, resetAt: 0 };

function rollTotalWindow() {
  if (Date.now() > loginFailsTotal.resetAt) {
    loginFailsTotal.count = 0;
    loginFailsTotal.resetAt = Date.now() + LOGIN_WINDOW_MS;
  }
}
`,
"global window");

sub(
`function loginThrottled(ip) {
  const rec = loginAttempts.get(ip);`,
`function loginThrottled(ip) {
  rollTotalWindow();
  if (loginFailsTotal.count >= LOGIN_MAX_FAILS_TOTAL) return true;
  const rec = loginAttempts.get(ip);`,
"throttle check");

sub(
`function noteFailedLogin(ip) {
  const rec = loginAttempts.get(ip);
  if (!rec || Date.now() > rec.resetAt) {`,
`function noteFailedLogin(ip) {
  rollTotalWindow();
  loginFailsTotal.count += 1;
  const rec = loginAttempts.get(ip);
  if (!rec || Date.now() > rec.resetAt) {
    // Карта не должна расти бесконечно от подменённых адресов.
    if (loginAttempts.size > 10000) loginAttempts.clear();`,
"note fail");

fs.writeFileSync("server.js", s);
EOF
